CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
INSERT OR IGNORE INTO schema_migrations VALUES (1, datetime('now'));
CREATE TABLE IF NOT EXISTS admins(id INTEGER PRIMARY KEY, email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'admin', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY, admin_id INTEGER REFERENCES admins(id) ON DELETE CASCADE, csrf TEXT NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS login_attempts(key TEXT PRIMARY KEY, count INTEGER NOT NULL, reset_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS media_assets(id INTEGER PRIMARY KEY, storage_key TEXT UNIQUE NOT NULL, mime_type TEXT NOT NULL, size_bytes INTEGER NOT NULL, width INTEGER NOT NULL, height INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS categories(id INTEGER PRIMARY KEY, name TEXT NOT NULL, normalized_name TEXT UNIQUE NOT NULL, slug TEXT UNIQUE NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS products(id INTEGER PRIMARY KEY, slug TEXT UNIQUE, name TEXT NOT NULL, price_idr INTEGER, availability TEXT NOT NULL DEFAULT 'available' CHECK(availability IN ('available','unavailable')), description TEXT NOT NULL DEFAULT '', category_id INTEGER REFERENCES categories(id) ON DELETE RESTRICT, image_asset_id INTEGER REFERENCES media_assets(id), publication_status TEXT NOT NULL DEFAULT 'draft' CHECK(publication_status IN ('draft','published')), published_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, CHECK(publication_status='draft' OR (length(name)>=3 AND price_idr IS NOT NULL AND price_idr BETWEEN 1 AND 999999999999 AND length(description)>=10 AND category_id IS NOT NULL AND image_asset_id IS NOT NULL AND slug IS NOT NULL AND published_at IS NOT NULL)));
CREATE INDEX IF NOT EXISTS product_public_date ON products(publication_status,published_at DESC,id DESC);
CREATE INDEX IF NOT EXISTS product_public_price ON products(publication_status,price_idr,id);
CREATE INDEX IF NOT EXISTS product_category ON products(category_id,publication_status);
CREATE TABLE IF NOT EXISTS about_content(id INTEGER PRIMARY KEY CHECK(id=1), title TEXT NOT NULL, home_summary TEXT NOT NULL, description TEXT NOT NULL, image_asset_id INTEGER REFERENCES media_assets(id), image_alt TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS contact_content(id INTEGER PRIMARY KEY CHECK(id=1), whatsapp TEXT NOT NULL DEFAULT '', phone TEXT NOT NULL DEFAULT '', email TEXT NOT NULL DEFAULT '', address TEXT NOT NULL, opening_hours TEXT NOT NULL, maps_url TEXT NOT NULL DEFAULT '', instagram_url TEXT NOT NULL DEFAULT '', facebook_url TEXT NOT NULL DEFAULT '', tiktok_url TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS gallery_items(id INTEGER PRIMARY KEY, image_asset_id INTEGER NOT NULL REFERENCES media_assets(id), title TEXT NOT NULL, caption TEXT NOT NULL DEFAULT '', alt_text TEXT NOT NULL, sort_order INTEGER NOT NULL DEFAULT 0, is_published INTEGER NOT NULL DEFAULT 0 CHECK(is_published IN (0,1)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS gallery_order ON gallery_items(is_published,sort_order,id);
CREATE TABLE IF NOT EXISTS contact_links(id INTEGER PRIMARY KEY, name TEXT NOT NULL, url TEXT NOT NULL, sort_order INTEGER NOT NULL DEFAULT 0);
